function farmT(
    game: GameRuntime,
    key: string,
    fallbackFr: string,
    fallbackEnOrVars?: string | Record<string, string | number>,
    maybeVars?: Record<string, string | number>,
): string {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    let fallback = fallbackFr;
    let vars: Record<string, string | number> = {};
    if (typeof fallbackEnOrVars === 'string') {
        fallback = lang === 'en' ? fallbackEnOrVars : fallbackFr;
        vars = maybeVars ?? {};
    } else if (fallbackEnOrVars) {
        vars = fallbackEnOrVars;
    }
    if (typeof game.t === 'function') {
        const got = game.t(key, vars);
        if (got && got !== key) return got;
    }
    let out = fallback;
    for (const [k, v] of Object.entries(vars)) {
        out = out.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
    return out;
}

function itemLabel(game: GameRuntime, itemKey: string): string {
    const def = (ALL_ITEMS as Record<string, Record<string, unknown>>)[itemKey];
    if (typeof game.getLocalizedItemName === 'function') {
        return game.getLocalizedItemName(itemKey, coerceStr(def?.name, itemKey), def);
    }
    return coerceStr(def?.name, itemKey);
}

function itemIconUrl(itemKey: string | null | undefined): string | null {
    if (!itemKey) return null;
    return getItemIconPath(itemKey);
}

const PASTURE_HEAL_ITEM_KEYS = ['super_potion', 'potion_max'] as const;

function buildPastureHealOptions(
    game: GameRuntime,
    state: MiltankFarmState,
    selectedUid: string,
    now: number,
    lang: 'fr' | 'en',
): MiltankPastureHealOptionSnapshot[] {
    const debuff = getActiveDebuffForPasture(state, selectedUid, now);
    const hasDebuff = !!debuff;
    const remainingMs = debuff ? Math.max(0, debuff.until - now) : 0;
    return PASTURE_HEAL_ITEM_KEYS.map((itemKey) => {
        const pct = getPastureHealReductionPct(itemKey) ?? 0;
        const owned = Math.max(0, Number(game.items?.[itemKey]) || 0);
        const reducedMs = Math.floor(MILTANK_FARM_THREATS.predatorDurationMs * pct);
        const reductionLabel = farmT(
            game,
            'miltankFarm.pastureHealReduction',
            '−{pct}%',
            '−{pct}%',
            { pct: Math.round(pct * 100) },
        );
        let effectPreviewLabel: string | null = null;
        if (hasDebuff) {
            if (reducedMs >= remainingMs) {
                effectPreviewLabel = lang === 'en' ? 'Cures immediately ✨' : 'Guérison immédiate ✨';
            } else {
                const curStr = formatFarmDuration(remainingMs, lang);
                const nextStr = formatFarmDuration(remainingMs - reducedMs, lang);
                effectPreviewLabel = `${curStr} → ${nextStr}`;
            }
        } else {
            const minStr = Math.round(reducedMs / 60_000);
            effectPreviewLabel = `−${minStr} min`;
        }
        let blockedLabel: string | null = null;
        if (!hasDebuff) {
            blockedLabel = farmT(
                game,
                'miltankFarm.pastureHealNoDebuff',
                'Pas de blessure active',
                'No active injury',
            );
        } else if (owned < 1) {
            blockedLabel = farmT(
                game,
                'miltankFarm.pastureHealNoItem',
                'Aucune potion en sac',
                'No potions in bag',
            );
        }
        return {
            itemKey,
            itemName: itemLabel(game, itemKey),
            itemIconUrl: itemIconUrl(itemKey),
            owned,
            reductionLabel,
            effectPreviewLabel,
            canUse: hasDebuff && owned >= 1,
            blockedLabel,
        };
    });
}

function isCreatureInUltimateSlot(game: GameRuntime, uid: string): boolean {
    const ult = game.ultimateSlot;
    return !!(ult && ult.uid && String(ult.uid) === uid);
}

function pastureSourceLabel(game: GameRuntime, source: PastureRosterSource): string {
    const keys: Record<PastureRosterSource, [string, string]> = {
        storage: ['miltankFarm.sourceStorage', 'Stockage'],
        team: ['miltankFarm.sourceTeam', 'Équipe'],
        pension: ['miltankFarm.sourcePension', 'Pension'],
    };
    const [key, fallback] = keys[source];
    return farmT(game, key, fallback, {});
}

function buildPastureCandidates(
    game: GameRuntime,
    state: MiltankFarmState,
    slot: PasturePlayerSlot,
): MiltankPastureCandidateSnapshot[] {
    const pastureUids = new Set(
        (state.pastureCreatures ?? [])
            .filter((c) => c?.uid)
            .map((c) => String(c.uid)),
    );
    const candidates: MiltankPastureCandidateSnapshot[] = [];
    const sources: PastureRosterSource[] = ['storage', 'team', 'pension'];

    for (const source of sources) {
        const arr = source === 'storage'
            ? game.storage
            : source === 'team'
                ? game.playerTeam
                : game.pension;
        if (!Array.isArray(arr)) continue;
        arr.forEach((creature, index) => {
            if (!creature || !isPastureMiltank(creature)) return;
            const uid = String(creature.uid || '');
            if (!uid || pastureUids.has(uid)) return;
            if (isCreatureInUltimateSlot(game, uid)) return;
            if (!canAssignCreatureToPastureSlot(creature, slot)) return;
            if (slot === 'shiny' && !getPastureNormalCreature(state)) return;
            candidates.push({
                source,
                index,
                uid,
                name: creature.name || 'Miltank',
                shiny: !!creature.isShiny,
                sourceLabel: pastureSourceLabel(game, source),
            });
        });
    }
    return candidates;
}

function buildPastureAssignSlots(
    game: GameRuntime,
    state: MiltankFarmState,
    lang: 'fr' | 'en',
): PastureAssignSlotSnapshot[] {
    if (!state.unlocked) return [];

    const normal = getPastureNormalCreature(state);
    const shiny = getPastureShinyCreature(state);
    const narrativeName = getNarrativeMiltankDisplayName(game);

    return [
        {
            kind: 'narrative',
            label: narrativeName,
            filled: true,
            uid: NARRATIVE_MILTANK_UID,
            name: null,
            shiny: false,
            empty: false,
            reserved: false,
            canUnassign: false,
        },
        {
            kind: 'normal',
            label: farmT(game, 'miltankFarm.pastureSlotNormal', 'Normal', 'Normal'),
            filled: !!normal,
            uid: normal?.uid ? String(normal.uid) : null,
            name: normal?.name?.trim() || null,
            shiny: false,
            empty: !normal,
            reserved: false,
            canUnassign: !!normal,
        },
        {
            kind: 'shiny',
            label: farmT(game, 'miltankFarm.pastureSlotShiny', 'Chromatique', 'Shiny'),
            filled: !!shiny,
            uid: shiny?.uid ? String(shiny.uid) : null,
            name: shiny?.name?.trim() || null,
            shiny: true,
            empty: !shiny,
            reserved: true,
            canUnassign: !!shiny,
        },
    ];
}

function getPastureSlotIndex(state: MiltankFarmState, pastureUid: string): number {
    const entries = state.pastureEntries ?? [];
    const idx = entries.findIndex((e) => e.uid === pastureUid);
    return idx >= 0 ? idx : 0;
}

function buildGuardianCandidateSnapshot(
    creature: import('../types/creature.js').CreatureData,
    fields: Omit<MiltankGuardianCandidateSnapshot, 'level' | 'prestige' | 'combatPower'>,
): MiltankGuardianCandidateSnapshot {
    return {
        ...fields,
        ...getGuardianCandidateStats(creature),
    };
}

function buildThreatCombatCandidates(
    game: GameRuntime,
    state: MiltankFarmState,
    pastureUid: string,
): MiltankGuardianCandidateSnapshot[] {
    const base = buildGuardianCandidates(game, state, pastureUid);
    const assigned = getGuardianForPastureUid(state, pastureUid);
    let candidates = base;
    if (assigned?.uid) {
        const uid = String(assigned.uid);
        if (!base.some((c) => c.uid === uid)) {
            const species = getMiltankFarmSpeciesKey(assigned);
            candidates = [buildGuardianCandidateSnapshot(assigned, {
                pastureUid,
                source: 'assigned',
                index: 0,
                uid,
                name: assigned.name || species,
                shiny: !!assigned.isShiny,
                species,
                sourceLabel: farmT(game, 'miltankFarm.guardianAssignedTag', 'Gardien assigné'),
                spriteUrl: getPokemonSpriteUrl(species, !!assigned.isShiny, false),
            }), ...base];
        }
    }
    return [...candidates].sort(compareGuardianCandidatesByPower);
}

function buildActiveThreatSprites(
    game: GameRuntime,
    state: MiltankFarmState,
    now: number,
    lang: 'fr' | 'en',
): MiltankThreatSpriteSnapshot[] {
    const approaches = state.activeThreatApproaches ?? [];
    const fromApproaches = approaches.map((approach: FarmThreatApproach) => {
        const slot = getPastureSlotIndex(state, approach.pastureUid);
        const displaySpecies = getFarmThreatCombatSpecies(approach);
        const approachSide = normalizeThreatApproachSide(approach);
        const progress = getThreatApproachProgress(approach, now);
        const label = approach.type === 'rocket'
            ? farmT(game, 'miltankFarm.threatRocketApproach', 'Team Rocket approche !', 'Team Rocket is approaching!')
            : farmT(
                game,
                'miltankFarm.threatPredatorApproach',
                '{species} approche !',
                '{species} is approaching!',
                { species: approach.species },
            );
        const spriteUrl = hasGuardianOverworldSprites(displaySpecies)
            ? null
            : getPokemonSpriteUrl(displaySpecies, false, false);
        return {
            id: approach.id,
            pastureUid: approach.pastureUid,
            type: approach.type,
            species: approach.species,
            displaySpecies,
            approachSide,
            approachFacing: getThreatApproachFacing(slot, approachSide),
            progress,
            spriteUrl,
            walkClass: `threat-approach-slot-${slot}-from-${approachSide}`,
            label,
            phase: 'approaching' as const,
        };
    });

    const fromAttacks = (state.pendingThreatAttacks ?? []).map((attack) => {
        const slot = getPastureSlotIndex(state, attack.pastureUid);
        const displaySpecies = getFarmThreatCombatSpecies(pendingAttackToApproach(attack));
        const approachSide = attack.approachSide === 'right' ? 'right' as const : 'left' as const;
        const lunge = getThreatAttackLunge(attack, slot, now);
        const label = attack.type === 'rocket'
            ? farmT(game, 'miltankFarm.threatRocketApproach', 'Team Rocket approche !', 'Team Rocket is approaching!')
            : farmT(
                game,
                'miltankFarm.threatPredatorApproach',
                '{species} approche !',
                '{species} is approaching!',
                { species: attack.species },
            );
        const spriteUrl = hasGuardianOverworldSprites(displaySpecies)
            ? null
            : getPokemonSpriteUrl(displaySpecies, false, false);
        return {
            id: attack.id,
            pastureUid: attack.pastureUid,
            type: attack.type,
            species: attack.species,
            displaySpecies,
            approachSide,
            approachFacing: getThreatApproachFacing(slot, approachSide),
            progress: 0,
            spriteUrl,
            walkClass: `threat-attack-slot-${slot}`,
            label,
            phase: 'attacking' as const,
            attackFromLeft: lunge.fromLeft,
            attackFromTop: lunge.fromTop,
            attackToLeft: lunge.toLeft,
            attackToTop: lunge.toTop,
            attackElapsedMs: lunge.elapsedMs,
            attackDurationMs: getThreatAttackLungeDurationMsForAttack(attack),
            arrivedAtPasture: !!attack.arrivedAtPasture,
            threatVanishDelayMs: getThreatHitGlowDelayMs(attack, now),
            threatGlowDurationMs: MILTANK_FARM_THREATS.threatAttackGlowDurationMs,
        };
    });

    return [...fromApproaches, ...fromAttacks];
}

function pastureThreatHitGlowDelayMs(
    state: MiltankFarmState,
    pastureUid: string,
    now: number,
): number | null {
    const attack = (state.pendingThreatAttacks ?? []).find((a) => a.pastureUid === pastureUid);
    if (!attack) return null;
    return getThreatHitGlowDelayMs(attack, now);
}

function kalosPastureQuestDone(game: GameRuntime): boolean {
    const completed = game.completedStoryQuests;
    return Array.isArray(completed) && completed.includes('story_kalos_miltank_pasture');
}

function guardianCreatureSpriteUrl(creature: { name?: string; species?: unknown; isShiny?: boolean } | null): string | null {
    if (!creature) return null;
    const species = getMiltankFarmSpeciesKey(creature as import('../types/creature.js').CreatureData);
    if (!species) return null;
    return getPokemonSpriteUrl(species, !!creature.isShiny, false);
}

function buildGuardianCandidates(
    game: GameRuntime,
    state: MiltankFarmState,
    pastureUid: string,
): MiltankGuardianCandidateSnapshot[] {
    const guardianUids = new Set(
        (state.guardianAssignments ?? [])
            .filter((a) => a?.creature?.uid)
            .map((a) => String(a.creature.uid)),
    );
    const pastureUids = new Set(
        (state.pastureCreatures ?? [])
            .filter((c) => c?.uid)
            .map((c) => String(c.uid)),
    );
    const candidates: MiltankGuardianCandidateSnapshot[] = [];
    const sources: PastureRosterSource[] = ['storage', 'team', 'pension'];

    for (const source of sources) {
        const arr = source === 'storage'
            ? game.storage
            : source === 'team'
                ? game.playerTeam
                : game.pension;
        if (!Array.isArray(arr)) continue;
        arr.forEach((creature, index) => {
            if (!creature || !isGuardianSpecies(creature)) return;
            const uid = String(creature.uid || '');
            if (!uid || guardianUids.has(uid) || pastureUids.has(uid)) return;
            if (isCreatureInUltimateSlot(game, uid)) return;
            const species = getMiltankFarmSpeciesKey(creature);
            candidates.push(buildGuardianCandidateSnapshot(creature, {
                pastureUid,
                source,
                index,
                uid,
                name: creature.name || species,
                shiny: !!creature.isShiny,
                species,
                sourceLabel: pastureSourceLabel(game, source),
                spriteUrl: getPokemonSpriteUrl(species, !!creature.isShiny, false),
            }));
        });
    }
    return [...candidates].sort(compareGuardianCandidatesByPower);
}

function getPastureEntryAssignedIndex(state: MiltankFarmState, targetUid: string): number {
    let assignedIndex = 0;
    for (const entry of state.pastureEntries ?? []) {
        if (entry.uid === targetUid) {
            return assignedIndex;
        }
        if (!entry.isNarrative && entry.uid !== NARRATIVE_MILTANK_UID) {
            assignedIndex += 1;
        }
    }
    return 0;
}

function findRecentRepelledPulse(
    state: MiltankFarmState,
    pastureUid: string,
    now: number,
): FarmIncidentPulse | null {
    const ttl = MILTANK_FARM_THREATS.incidentPulseTtlMs;
    return (state.pendingIncidentPulses ?? []).find(
        (p) => p.pastureUid === pastureUid && p.type === 'repelled' && p.at >= now - ttl,
    ) ?? null;
}

function getRecentRepelledPulses(state: MiltankFarmState, now: number): FarmIncidentPulse[] {
    const ttl = MILTANK_FARM_THREATS.incidentPulseTtlMs;
    return (state.pendingIncidentPulses ?? []).filter(
        (p) => p.type === 'repelled' && p.at >= now - ttl,
    );
}

function buildRepelledLabel(game: GameRuntime, pulse: FarmIncidentPulse | null): string | null {
    if (!pulse) return null;
    if (pulse.repelledThreat === 'rocket') {
        return farmT(game, 'miltankFarm.threatRepelledRocket', 'Gardien — Team Rocket repoussé', {});
    }
    if (pulse.repelledThreat === 'predator') {
        return farmT(game, 'miltankFarm.threatRepelledPredator', 'Gardien — {predator} repoussé', {
            predator: pulse.predatorSpecies ?? 'predator',
        });
    }
    return farmT(game, 'miltankFarm.log.guardianRepelled', 'Le gardien a repoussé la menace !', {});
}

function buildFarmRepelledAlertLabel(game: GameRuntime, pulses: FarmIncidentPulse[]): string | null {
    if (pulses.length === 0) return null;
    if (pulses.length === 1) return buildRepelledLabel(game, pulses[0] ?? null);
    return farmT(game, 'miltankFarm.threatRepelledMany', 'Gardiens — {count} menaces repoussées', {
        count: pulses.length,
    });
}

function buildIncidentAlertSnapshot(
    game: GameRuntime,
    state: MiltankFarmState,
    lang: 'fr' | 'en',
): MiltankFarmIncidentAlertSnapshot | null {
    const alert = state.pendingIncidentAlert;
    if (!alert) return null;
    if (alert.pastureUid !== state.selectedPastureUid) return null;
    const entry = getPastureEntryByUid(state, alert.pastureUid);
    if (!entry) return null;
    const miltankName = getPastureEntryDisplayName(game, state, entry);
    const dismissLabel = farmT(game, 'miltankFarm.incidentDismissBtn', 'OK', 'OK');
    if (alert.type === 'predator') {
        const duration = formatFarmDuration(MILTANK_FARM_THREATS.predatorDurationMs, lang);
        return {
            type: 'predator',
            title: farmT(
                game,
                'miltankFarm.incidentPredatorTitle',
                'Prédateur — production réduite',
                'Predator — reduced production',
            ),
            body: farmT(
                game,
                'miltankFarm.incidentPredatorBody',
                '{predator} a blessé {miltank} ! Production ÷2 pendant {duration}.',
                '{predator} injured {miltank}! Production halved for {duration}.',
                {
                    predator: alert.predatorSpecies ?? 'predator',
                    miltank: miltankName,
                    duration,
                },
            ),
            dismissLabel,
        };
    }
    return {
        type: 'rocket',
        title: farmT(
            game,
            'miltankFarm.incidentRocketTitle',
            'Team Rocket — lait volé !',
            'Team Rocket — milk stolen!',
        ),
        body: farmT(
            game,
            'miltankFarm.incidentRocketBody',
            'Team Rocket a volé {qty} lait sur {miltank}.',
            'Team Rocket stole {qty} milk from {miltank}.',
            {
                qty: alert.milkStolen ?? 0,
                miltank: miltankName,
            },
        ),
        dismissLabel,
    };
}

function buildSpriteMilkCycleFields(
    game: GameRuntime,
    storedMilk: number,
    pendingMilk: number,
    stockCap: number,
    milkPerHour: number,
    lang: 'fr' | 'en',
): Pick<MiltankPastureSpriteSnapshot, 'milkCyclePct' | 'nextMilkMs' | 'nextMilkLabel'> {
    const milkCyclePct = computeMilkCyclePct(pendingMilk);
    const nextMilkMs = computeNextMilkMs(
        Math.floor(storedMilk),
        pendingMilk,
        stockCap,
        milkPerHour,
    );
    const nextMilkLabel = nextMilkMs != null
        ? farmT(game, 'miltankFarm.nextMilkIn', 'Prochain lait dans {time}', {
            time: formatFarmDuration(nextMilkMs, lang),
        })
        : null;
    return { milkCyclePct, nextMilkMs, nextMilkLabel };
}

function buildPastureSprites(
    game: GameRuntime,
    state: MiltankFarmState,
    lang: string,
    now: number,
    threatsUnlocked: boolean,
    selectedUid: string,
    milkOpts?: { milkSpeedMult?: number },
): MiltankPastureSpriteSnapshot[] {
    const sprites: MiltankPastureSpriteSnapshot[] = [];
    const narrative = getPastureEntryByUid(state, NARRATIVE_MILTANK_UID);
    let assignedIdx = 0;
    if (narrative) {
        const milkPerHour = computePastureEntryMilkPerHour(state, narrative, assignedIdx, now, milkOpts);
        const baseMilkPerHour = computePastureEntryBaseMilkPerHour(state, narrative, assignedIdx, now, milkOpts);
        const debuffMult = getPastureProductionMult(state, NARRATIVE_MILTANK_UID, now);
        const guardian = getGuardianForPastureUid(state, NARRATIVE_MILTANK_UID);
        const debuff = getActiveDebuffForPasture(state, NARRATIVE_MILTANK_UID, now);
        const recentTheft = (state.pendingIncidentPulses ?? []).some(
            (p) => p.pastureUid === NARRATIVE_MILTANK_UID && p.type === 'rocket' && p.at >= now - MILTANK_FARM_THREATS.incidentPulseTtlMs,
        );
        const repelledPulse = findRecentRepelledPulse(state, NARRATIVE_MILTANK_UID, now);
        const narrativeStockCap = getPastureEntryStockCap(state, narrative);
        sprites.push({
            uid: NARRATIVE_MILTANK_UID,
            name: getNarrativeMiltankDisplayName(game),
            isNarrative: true,
            storedMilk: Math.floor(narrative.storedMilk),
            pendingFraction: narrative.pendingMilk,
            ...buildSpriteMilkCycleFields(
                game,
                narrative.storedMilk,
                narrative.pendingMilk,
                narrativeStockCap,
                milkPerHour,
                lang as 'fr' | 'en',
            ),
            canClaim: Math.floor(narrative.storedMilk) > 0,
            shiny: false,
            walkClass: 'miltank-walk-0',
            milkPerHour,
            baseMilkPerHour,
            debuffProductionMult: debuffMult,
            guardianUid: guardian?.uid ? String(guardian.uid) : null,
            guardianName: guardian?.name ?? null,
            guardianSpecies: guardian ? getMiltankFarmSpeciesKey(guardian) : null,
            guardianSpriteUrl: guardianCreatureSpriteUrl(guardian),
            guardianShiny: !!guardian?.isShiny,
            guardianWalkClass: guardian ? 'guardian-walk-0' : null,
            hasGuardian: !!guardian,
            debuffActive: !!debuff,
            debuffRemainingMs: debuff ? Math.max(0, debuff.until - now) : 0,
            debuffLabel: debuff
                ? farmT(game, 'miltankFarm.threatPredatorDebuff', 'Blessée ({time})', {
                    time: formatFarmDuration(Math.max(0, debuff.until - now), lang as 'fr' | 'en'),
                })
                : null,
            recentTheft,
            recentRepelled: !!repelledPulse,
            repelledLabel: buildRepelledLabel(game, repelledPulse),
            unprotected: threatsUnlocked && !guardian,
            level: narrative.level,
            satiety: getDisplaySatiety(narrative.satiety, getEntrySatietyMax(narrative)),
            satietyMax: getEntrySatietyMax(narrative),
            stockCap: narrativeStockCap,
            isSelected: selectedUid === NARRATIVE_MILTANK_UID,
            requestItemKey: narrative.currentRequest?.itemKey ?? null,
            requestItemIconUrl: itemIconUrl(narrative.currentRequest?.itemKey),
            threatHitGlowDelayMs: pastureThreatHitGlowDelayMs(state, NARRATIVE_MILTANK_UID, now),
        });
    }

    let walkIdx = 1;
    for (const creature of state.pastureCreatures ?? []) {
        if (!creature?.uid) continue;
        const entry = getPastureEntryByUid(state, String(creature.uid));
        if (!entry) continue;
        const milkPerHour = computePastureEntryMilkPerHour(state, entry, assignedIdx, now, milkOpts);
        const baseMilkPerHour = computePastureEntryBaseMilkPerHour(state, entry, assignedIdx, now, milkOpts);
        assignedIdx += 1;
        const pastureUid = String(creature.uid);
        const debuffMult = getPastureProductionMult(state, pastureUid, now);
        const guardian = getGuardianForPastureUid(state, pastureUid);
        const debuff = getActiveDebuffForPasture(state, pastureUid, now);
        const recentTheft = (state.pendingIncidentPulses ?? []).some(
            (p) => p.pastureUid === pastureUid && p.type === 'rocket' && p.at >= now - MILTANK_FARM_THREATS.incidentPulseTtlMs,
        );
        const repelledPulse = findRecentRepelledPulse(state, pastureUid, now);
        const entryStockCap = getPastureEntryStockCap(state, entry);
        sprites.push({
            uid: pastureUid,
            name: creature.name || 'Miltank',
            isNarrative: false,
            storedMilk: Math.floor(entry.storedMilk),
            pendingFraction: entry.pendingMilk,
            ...buildSpriteMilkCycleFields(
                game,
                entry.storedMilk,
                entry.pendingMilk,
                entryStockCap,
                milkPerHour,
                lang as 'fr' | 'en',
            ),
            canClaim: Math.floor(entry.storedMilk) > 0,
            shiny: !!creature.isShiny,
            walkClass: `miltank-walk-${walkIdx % 3}`,
            milkPerHour,
            baseMilkPerHour,
            debuffProductionMult: debuffMult,
            guardianUid: guardian?.uid ? String(guardian.uid) : null,
            guardianName: guardian?.name ?? null,
            guardianSpecies: guardian ? getMiltankFarmSpeciesKey(guardian) : null,
            guardianSpriteUrl: guardianCreatureSpriteUrl(guardian),
            guardianShiny: !!guardian?.isShiny,
            guardianWalkClass: guardian ? `guardian-walk-${walkIdx % 3}` : null,
            hasGuardian: !!guardian,
            debuffActive: !!debuff,
            debuffRemainingMs: debuff ? Math.max(0, debuff.until - now) : 0,
            debuffLabel: debuff
                ? farmT(game, 'miltankFarm.threatPredatorDebuff', 'Blessée ({time})', {
                    time: formatFarmDuration(Math.max(0, debuff.until - now), lang as 'fr' | 'en'),
                })
                : null,
            recentTheft,
            recentRepelled: !!repelledPulse,
            repelledLabel: buildRepelledLabel(game, repelledPulse),
            unprotected: threatsUnlocked && !guardian,
            level: entry.level,
            satiety: getDisplaySatiety(entry.satiety, getEntrySatietyMax(entry)),
            satietyMax: getEntrySatietyMax(entry),
            stockCap: entryStockCap,
            isSelected: selectedUid === pastureUid,
            requestItemKey: entry.currentRequest?.itemKey ?? null,
            requestItemIconUrl: itemIconUrl(entry.currentRequest?.itemKey),
            threatHitGlowDelayMs: pastureThreatHitGlowDelayMs(state, pastureUid, now),
        });
        walkIdx += 1;
    }
    return sprites;
}

function buildTalentBranchSnapshots(
    game: GameRuntime,
    entry: MiltankPastureEntry,
    state: MiltankFarmState,
    lang: 'fr' | 'en',
): MiltankFarmTalentBranchSnapshot[] {
    const branches: MiltankFarmTalentBranch[] = ['production', 'milk_potency', 'care'];
    return branches.map((key) => {
        const def = MILTANK_FARM_TALENT_BRANCHES[key];
        const rank = getTalentRank(entry, key);
        let bonusText = '';
        let nextBonusText: string | null = null;
        let description = '';
        if (key === 'production') {
            description = lang === 'en' ? 'Faster milking speed' : 'Vitesse de traite accrue';
            const curPct = (rank * MILTANK_FARM_TALENTS.productionPerRank * 100).toFixed(0);
            bonusText = `+${curPct} %`;
            if (rank < def.maxRank) {
                const nextPct = ((rank + 1) * MILTANK_FARM_TALENTS.productionPerRank * 100).toFixed(0);
                nextBonusText = `+${nextPct} % prod.`;
            } else {
                bonusText = `+${curPct} % prod. (MAX)`;
            }
        } else if (key === 'milk_potency') {
            description = lang === 'en' ? 'Increases vitamin efficiency' : 'Efficacité accrue des vitamines';
            const curPct = formatMilkVitaminPercent(getMoomooMilkVitaminBonusPerUse(state));
            bonusText = `${curPct} %`;
            if (rank < def.maxRank) {
                const nextPct = formatMilkVitaminPercent(
                    getMoomooMilkVitaminBonusPerUse(state) + MILTANK_FARM_TALENTS.milkPotencyPerRank,
                );
                nextBonusText = `${nextPct} % / vit.`;
            } else {
                bonusText = `${curPct} % (MAX)`;
            }
        } else {
            description = lang === 'en' ? 'Fuller for longer & easier meals' : 'Satiété prolongée et repas facilités';
            if (rank <= 3) {
                bonusText = `+${rank * 10} %`;
                if (rank < def.maxRank) {
                    nextBonusText = `+${(rank + 1) * 10} % durée satiété`;
                }
            } else if (rank <= 5) {
                bonusText = `+${(rank - 3) * 15} %`;
                if (rank < def.maxRank) {
                    nextBonusText = `+${(rank - 2) * 15} % boost repas`;
                }
            } else if (rank === 6) {
                bonusText = '+0 XP';
                nextBonusText = '+1 XP par repas';
            } else {
                bonusText = '+10 sat.';
                nextBonusText = null;
            }
            if (rank >= def.maxRank) {
                bonusText = `${bonusText} (MAX)`;
            }
        }
        return {
            key,
            label: farmT(game, `miltankFarm.talent.${key}`, key),
            description,
            rank,
            maxRank: def.maxRank,
            bonusText,
            nextBonusText,
            canInvest: canInvestTalentForEntry(entry, key),
        };
    });
}

