function buildFarmActionIndicators(
    game: GameRuntime,
    state: MiltankFarmState,
    farmStoredMilk: number,
): Pick<
    MiltankFarmSnapshot,
    | 'farmHasClaimAction'
    | 'farmHasFeedAction'
    | 'farmHasTalentAction'
    | 'farmActionBadgeCount'
    | 'farmActionBadgeTitle'
> {
    const farmHasClaimAction = farmStoredMilk > 0;
    let farmHasFeedAction = false;
    let farmHasTalentAction = false;

    for (const entry of state.pastureEntries ?? []) {
        if (getUnspentTalentPoints(entry) > 0) farmHasTalentAction = true;
        const req = entry.currentRequest;
        const reqKey = req?.itemKey ?? null;
        const reqQty = req?.qty ?? 0;
        if (!reqKey || reqQty <= 0) continue;
        const owned = Math.max(0, Number(game.items?.[reqKey]) || 0);
        if (owned >= reqQty && canFeedEntryBySatiety(entry)) {
            farmHasFeedAction = true;
        }
    }

    const farmActionBadgeCount =
        (farmHasClaimAction ? 1 : 0)
        + (farmHasFeedAction ? 1 : 0)
        + (farmHasTalentAction ? 1 : 0);

    let farmActionBadgeTitle: string | null = null;
    if (farmActionBadgeCount > 0) {
        const parts: string[] = [];
        if (farmHasClaimAction) {
            parts.push(farmT(game, 'miltankFarm.farmActionClaim', 'récolte', {}));
        }
        if (farmHasFeedAction) {
            parts.push(farmT(game, 'miltankFarm.farmActionFeed', 'nourriture', {}));
        }
        if (farmHasTalentAction) {
            parts.push(farmT(game, 'miltankFarm.farmActionTalent', 'talents', {}));
        }
        farmActionBadgeTitle = farmT(
            game,
            'miltankFarm.farmActionBadgeTitle',
            'Actions : {actions}',
            { actions: parts.join(', ') },
        );
    }

    return {
        farmHasClaimAction,
        farmHasFeedAction,
        farmHasTalentAction,
        farmActionBadgeCount,
        farmActionBadgeTitle,
    };
}

function buildStockFullLabel(
    game: GameRuntime,
    lang: 'fr' | 'en',
    stored: number,
    pending: number,
    cap: number,
    milkPerHour: number,
): { fillPct: number; fullInMs: number | null; label: string | null } {
    const fillPct = computeStockFillPct(stored, pending, cap);
    const fullInMs = computeStockFullMs(stored, pending, cap, milkPerHour);
    const label = fullInMs == null
        ? (fillPct >= 100
            ? farmT(game, 'miltankFarm.stockFullNow', 'Réserve pleine', {})
            : null)
        : farmT(game, 'miltankFarm.stockFullIn', 'Plein dans {time}', {
            time: formatFarmDuration(fullInMs, lang),
        });
    return { fillPct, fullInMs, label };
}

