export function buildMiltankFarmSnapshot(game: GameRuntime): MiltankFarmSnapshot {
    const lang = (typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr') as 'fr' | 'en';
    let state: MiltankFarmState | null = game.miltankFarmState;
    const unlocked = !!(state?.unlocked || game.unlockedFeatures?.miltankFarm);
    const now = Date.now();
    const farmViewActive = !!game.miltankFarmViewActive;

    if (!unlocked) {
        return emptySnapshot(game, farmViewActive);
    }

    if (!state) {
        state = createDefaultMiltankFarmState(now);
        state.unlocked = true;
        game.miltankFarmState = state;
    }

    normalizeMiltankFarmState(state);

    const selected = getSelectedPastureEntry(state) ?? getNarrativePastureEntry(state);
    const farmLevelSum = state.level;
    const xpProgress = getPastureEntryXpProgress(selected);
    const req = selected.currentRequest;
    const reqKey = req?.itemKey ?? null;
    const reqQty = req?.qty ?? 0;
    const owned = reqKey ? Math.max(0, Number(game.items?.[reqKey]) || 0) : 0;
    const stockCap = getPastureEntryStockCap(state, selected);
    const selectedAssignedIndex = getPastureEntryAssignedIndex(state, selected.uid);
    const milkSpeedMult = game.getMasteryBonus?.('miltank_milk_speed_mult') || 0;
    const milkOpts = milkSpeedMult > 0 ? { milkSpeedMult } : undefined;
    const selectedMilkPerHour = computePastureEntryMilkPerHour(
        state,
        selected,
        selectedAssignedIndex,
        now,
        milkOpts,
    );
    const selectedBaseMilkPerHour = computePastureEntryBaseMilkPerHour(
        state,
        selected,
        selectedAssignedIndex,
        now,
        milkOpts,
    );
    const selectedDebuffMult = getPastureProductionMult(state, selected.uid, now);
    const selectedDebuffLossPct = selectedDebuffMult < 1
        ? Math.round((1 - selectedDebuffMult) * 100)
        : 0;
    const milkPerHour = computeMiltankMilkPerHour(state, { milkSpeedMult }, now);
    const threatCtx = {
        teamRocketUnlocked: !!(game.unlockedFeatures?.teamRocketTab),
        pastureQuestCompleted: kalosPastureQuestDone(game),
    };
    const threatsUnlocked = areFarmThreatsUnlocked(state);
    const guardiansUnlocked = areGuardiansUnlocked(state, threatCtx);
    const guardianUnlockHint = guardiansUnlocked
        ? null
        : farmT(
            game,
            'miltankFarm.guardianLocked',
            'Gardiens : complète la quête pâturage du Village Pokémon.',
            'Guardians: complete the Pokemon Village pasture quest.',
        );
    const pastureSprites = buildPastureSprites(
        game,
        state,
        lang,
        now,
        threatsUnlocked,
        state.selectedPastureUid,
        milkOpts,
    );
    const totalStored = pastureSprites.reduce((s, p) => s + p.storedMilk, 0);
    const totalStockCap = pastureSprites.reduce((s, p) => s + p.stockCap, 0);
    const farmMilkPerHour = milkPerHour;
    const nextPastureSlot = getNextPasturePlayerSlot(state);
    const pastureCandidates = nextPastureSlot
        ? buildPastureCandidates(game, state, nextPastureSlot)
        : [];
    const pastureAssignSlots = buildPastureAssignSlots(game, state, lang);

    const selectedSatietyMax = getEntrySatietyMax(selected);
    const careRank = getTalentRank(selected, 'care');
    const careSatietyDecayPct = getCareSatietyDecayPct(careRank);
    const careBoostDurationPct = getCareBoostDurationPct(careRank);
    const careSatietyBadge = careSatietyDecayPct > 0
        ? farmT(
            game,
            'miltankFarm.careSatietyBadge',
            '+{pct} % rassasié',
            '+{pct}% fuller',
            { pct: careSatietyDecayPct },
        )
        : null;
    const careSatietyCapBadge = selectedSatietyMax > MILTANK_FARM.satietyMax
        ? farmT(game, 'miltankFarm.careSatietyCapBadge', 'max {max}', { max: selectedSatietyMax })
        : null;
    const satietyDecayMult = getCareSatietyDecayMult(selected);

    const feedBlockedReason = getFeedBlockedReason(
        selected.satiety,
        reqKey,
        reqQty,
        owned,
        req?.category,
        selectedSatietyMax,
    );
    const feedBlockedLabel = feedBlockedReason === 'satiety'
        ? farmT(
            game,
            'miltankFarm.feedBlockedSatietyNamed',
            '{name} est rassasiée — attends un peu',
            '{name} is full — wait a bit',
            { name: getPastureEntryDisplayName(game, state, selected) },
        )
        : feedBlockedReason === 'missing_items'
            ? farmT(game, 'miltankFarm.feedBlockedMissing', 'Objets manquants', {})
            : feedBlockedReason === 'no_request'
                ? farmT(game, 'miltankFarm.feedBlockedNoRequest', 'Aucune demande active', {})
                : null;

    const boostRemainingMs = Math.max(0, selected.productionBoostUntil - now);
    const boostRemainingLabel = boostRemainingMs > 0
        ? farmT(game, 'miltankFarm.boostCountdown', 'Boost — {time}', {
            time: formatFarmDuration(boostRemainingMs, lang),
        })
        : null;

    const requestExpiresInMs = req && req.expiresAt > now ? req.expiresAt - now : null;
    const requestExpiresLabel = requestExpiresInMs != null
        ? farmT(game, 'miltankFarm.requestExpires', 'Nouvelle envie dans {time}', {
            time: formatFarmDuration(requestExpiresInMs, lang),
        })
        : null;

    const satietyRoomMs = getSatietyRoomMs(
        selected.satiety,
        req?.category,
        selectedSatietyMax,
        satietyDecayMult,
    );
    const satietyRoomLabel = satietyRoomMs > 0
        ? farmT(game, 'miltankFarm.satietyCountdown', 'Peut manger dans {time}', {
            time: formatFarmDuration(satietyRoomMs, lang),
        })
        : null;

    const rerollCost = getNextMiltankRequestRerollCost(state, new Date(now));
    const canReroll = (Number(game.pokedollars) || 0) >= rerollCost;
    const rerollBlockedLabel = !canReroll
        ? farmT(game, 'miltankFarm.log.rerollPoor', 'Pas assez de Pokédollars.', 'Not enough Pokédollars.')
        : null;

    const selectedNextMilkMs = computeNextMilkMs(
        Math.floor(selected.storedMilk),
        selected.pendingMilk,
        stockCap,
        selectedMilkPerHour,
    );
    const narrativeNextMilkLabel = selectedNextMilkMs != null
        ? farmT(game, 'miltankFarm.nextMilkIn', 'Prochain lait dans {time}', {
            time: formatFarmDuration(selectedNextMilkMs, lang),
        })
        : null;

    const selectedStoredFloor = Math.floor(selected.storedMilk);
    const selectedStockGauge = buildStockFullLabel(
        game,
        lang,
        selectedStoredFloor,
        selected.pendingMilk,
        stockCap,
        selectedMilkPerHour,
    );
    const farmPendingMilk = pastureSprites.reduce((s, p) => s + p.pendingFraction, 0);
    const farmStockGauge = buildStockFullLabel(
        game,
        lang,
        totalStored,
        farmPendingMilk,
        totalStockCap,
        farmMilkPerHour,
    );
    const farmActionIndicators = buildFarmActionIndicators(game, state, totalStored);

    const vitaminEfficiencyPct = formatMilkVitaminPercent(getMoomooMilkVitaminBonusPerUse(state));
    const potencyRank = getTalentRank(selected, 'milk_potency');
    const milkPotencyNextPct = potencyRank < MILTANK_FARM_TALENT_BRANCHES.milk_potency.maxRank
        ? formatMilkVitaminPercent(getMoomooMilkVitaminBonusPerUse(state) + MILTANK_FARM_TALENTS.milkPotencyPerRank)
        : null;

    const assignedCount = (state.pastureCreatures ?? []).length;
    const secondPastureCareHint = assignedCount >= 2 && !state.uiHintsSeen?.secondPastureCare
        ? farmT(
            game,
            'miltankFarm.secondPastureCareHint',
            'Investir en Soin sur ce Miltank réduit l\'attente entre les repas et accélère sa montée de niveau.',
            {},
        )
        : null;
    const boostActive = selected.productionBoostUntil > now;
    const boostCareHint = boostActive && careBoostDurationPct > 0
        ? farmT(game, 'miltankFarm.boostCareHint', '+{pct} % durée (Soin)', { pct: careBoostDurationPct })
        : null;

    const combatActive = game.combatState === 'fighting' || game.combatState === 'starting';
    const farmThreatCombatActive = !!(
        game.gymTrainerState?.active
        && game.gymTrainerState.isFarmThreat
        && combatActive
    );

    const guardianCandidates = guardiansUnlocked
        ? pastureSprites
            .filter((s) => !s.hasGuardian)
            .flatMap((s) => buildGuardianCandidates(game, state, s.uid))
        : [];

    const selectedPastureSprite = pastureSprites.find((s) => s.uid === selected.uid) ?? null;
    const hasApproachingThreat = (state.activeThreatApproaches ?? []).length > 0;
    const activeThreatSprites = threatsUnlocked
        ? buildActiveThreatSprites(game, state, now, lang)
        : [];
    const selectedApproaching = activeThreatSprites.find((t) => t.pastureUid === selected.uid) ?? null;
    const selectedGuardianCandidates = guardiansUnlocked
        ? buildGuardianCandidates(game, state, selected.uid)
        : [];
    const pastureHealOptions = guardiansUnlocked
        ? buildPastureHealOptions(game, state, selected.uid, now, lang)
        : [];
    const selectedHasActiveThreat = !!(
        selectedPastureSprite?.debuffActive
        || selectedPastureSprite?.recentTheft
        || selectedApproaching
    );
    const selectedThreatAlertLabel = selectedApproaching
        ? selectedApproaching.label
        : selectedPastureSprite?.recentTheft
            ? farmT(game, 'miltankFarm.threatAlertRocket', 'Team Rocket — lait volé !', {})
            : selectedPastureSprite?.debuffActive
                ? farmT(game, 'miltankFarm.threatAlertPredator', 'Prédateur — production réduite', {})
                : null;

    const pendingThreatEngageId = state.pendingThreatEngageId ?? null;
    const engageApproach = pendingThreatEngageId
        ? getThreatApproachById(state, pendingThreatEngageId)
        : null;
    const threatCombatCandidates = engageApproach
        ? buildThreatCombatCandidates(game, state, engageApproach.pastureUid)
        : [];
    const threatApproachBannerLabel = hasApproachingThreat
        ? farmT(game, 'miltankFarm.threatApproachBanner', 'Une menace approche le pâturage !')
        : null;

    const hasActiveThreat = pastureSprites.some((s) => s.debuffActive || s.recentTheft)
        || hasApproachingThreat;
    const threatAlertLabel = hasApproachingThreat
        ? threatApproachBannerLabel
        : pastureSprites.some((s) => s.recentTheft)
            ? farmT(game, 'miltankFarm.threatAlertRocket', 'Team Rocket — lait volé !', {})
            : pastureSprites.some((s) => s.debuffActive)
                ? farmT(game, 'miltankFarm.threatAlertPredator', 'Prédateur — production réduite', {})
                : null;

    const recentRepelledPulses = getRecentRepelledPulses(state, now);
    const hasRecentRepelled = recentRepelledPulses.length > 0;
    const repelledAlertLabel = buildFarmRepelledAlertLabel(game, recentRepelledPulses);

    const threatCombatWins = Math.max(0, Math.floor(Number(state.threatCombatWins) || 0));
    const threatIntensity = getThreatCombatIntensity(threatCombatWins);
    const threatIntensityLabel = threatIntensity > 0
        ? farmT(game, 'miltankFarm.threatIntensity', 'Intensité menaces +{n}', 'Threat intensity +{n}', {
            n: threatIntensity,
        })
        : null;
    const incidentAlert = buildIncidentAlertSnapshot(game, state, lang);

    return {
        visible: true,
        unlocked: true,
        farmViewActive: !!game.miltankFarmViewActive,
        ui: buildUi(game),
        level: selected.level,
        farmLevelSum,
        farmStoredMilk: totalStored,
        farmStockCap: totalStockCap,
        farmMilkPerHour,
        selectedPastureUid: selected.uid,
        selectedPastureName: getPastureEntryDisplayName(game, state, selected),
        xp: xpProgress.xp,
        xpInLevel: xpProgress.xpInLevel,
        xpNeededInLevel: xpProgress.xpNeededInLevel,
        talentPointsAvailable: getUnspentTalentPoints(selected),
        talentBranches: buildTalentBranchSnapshots(game, selected, state, lang),
        storedMilk: Math.floor(selected.storedMilk),
        stockCap,
        pendingFraction: selected.pendingMilk,
        milkPerHour: selectedMilkPerHour,
        baseMilkPerHour: selectedBaseMilkPerHour,
        debuffProductionMult: selectedDebuffMult,
        debuffLossPct: selectedDebuffLossPct,
        requestItemKey: reqKey,
        requestItemName: reqKey ? itemLabel(game, reqKey) : null,
        requestItemIconUrl: itemIconUrl(reqKey),
        requestQty: reqQty,
        requestOwned: owned,
        canFeed: !!(reqKey && owned >= reqQty && canFeedEntryBySatiety(selected)),
        canClaim: totalStored > 0,
        canClaimSelected: Math.floor(selected.storedMilk) > 0,
        satiety: getDisplaySatiety(selected.satiety, selectedSatietyMax),
        satietyMax: selectedSatietyMax,
        careSatietyDecayPct,
        careSatietyBadge,
        careSatietyCapBadge,
        boostActive,
        careBoostDurationPct,
        boostCareHint,
        pastureUpgraded: state.pastureUpgraded,
        rerollCost,
        pastureSprites,
        maxAssignableSlots: state.maxAssignableSlots ?? 2,
        assignedCount,
        nextPastureSlot,
        pastureCandidates,
        pastureAssignSlots,
        combatActiveWhileFarm: combatActive && !!game.miltankFarmViewActive,
        farmThreatCombatActive,
        boostRemainingMs,
        boostRemainingLabel,
        requestExpiresInMs,
        requestExpiresLabel,
        satietyRoomMs,
        satietyRoomLabel,
        feedBlockedReason,
        feedBlockedLabel,
        canReroll,
        rerollCooldownMs: 0,
        rerollCooldownLabel: null,
        rerollBlockedLabel,
        narrativeNextMilkMs: selectedNextMilkMs,
        narrativeNextMilkLabel,
        stockFillPct: selectedStockGauge.fillPct,
        stockFullInMs: selectedStockGauge.fullInMs,
        stockFullLabel: selectedStockGauge.label,
        farmPendingMilk,
        farmStockFillPct: farmStockGauge.fillPct,
        farmStockFullInMs: farmStockGauge.fullInMs,
        farmStockFullLabel: farmStockGauge.label,
        ...farmActionIndicators,
        pastureQuestHint: null,
        pastureQuestClarify: null,
        secondPastureCareHint,
        vitaminEfficiencyPct,
        milkPotencyNextPct,
        threatsUnlocked,
        guardiansUnlocked,
        guardianUnlockHint,
        guardianProgressHint: null,
        guardianProgressClarify: null,
        guardianCandidates,
        hasActiveThreat,
        threatAlertLabel,
        hasRecentRepelled,
        repelledAlertLabel,
        selectedPastureSprite,
        selectedGuardianCandidates,
        selectedHasActiveThreat,
        selectedThreatAlertLabel,
        activeThreatSprites,
        hasApproachingThreat,
        pendingThreatEngageId,
        threatCombatCandidates,
        threatApproachBannerLabel,
        threatCombatWins,
        threatIntensityLabel,
        incidentAlert,
        pastureHealOptions,
        berryTreeVisible: !!game.unlockedFeatures?.berryTree,
        berryTree: state.berryTree
            ? buildBerryTreeSnapshot(game, state.berryTree, state)
            : emptyBerryTreeSnapshot(game),
    };
}

let lastSnapshot: MiltankFarmSnapshot | null = null;
let publishGeneration = 0;
let lastLivePublishAt = 0;

/** @internal Vitest only */
export function resetMiltankFarmSnapshotDedupForTests(): void {
    lastSnapshot = null;
    publishGeneration = 0;
    lastLivePublishAt = 0;
}

export function getLastMiltankFarmLivePublishAtForTests(): number {
    return lastLivePublishAt;
}

export function notifyMiltankFarmChanged(
    game: GameRuntime,
    options?: { force?: boolean },
): void {
    const generation = ++publishGeneration;
    const snap = buildMiltankFarmSnapshot(game);
    if (generation !== publishGeneration) return;
    if (
        !options?.force
        && lastSnapshot
        && !miltankFarmSnapshotWouldChange(lastSnapshot, snap)
    ) {
        return;
    }
    lastSnapshot = snap;
    publish({ type: Evt.MILTANK_FARM_CHANGED, miltankFarm: snap });
}

/** Throttled publish while farm view or modal is open (timer + passive milk). */
export function maybePublishMiltankFarmLiveRefresh(
    game: GameRuntime,
    now: number,
    shouldRefresh: boolean,
): void {
    if (!shouldRefresh) return;
    if (now - lastLivePublishAt < 1000) return;
    lastLivePublishAt = now;
    notifyMiltankFarmChanged(game, { force: true });
}

/** @internal Vitest */
export { computePastureEntryMilkPerHour };
