/**
 * Guardian picker — level / prestige / combat power for sorting and display.
 */

import type { CreatureData } from '../types/creature.js';
import { getCreatureCombatPower } from './creatureCombatPower.ts';

export interface GuardianCandidateStats {
    level: number;
    prestige: number;
    combatPower: number;
}

export function getGuardianCandidateStats(creature: CreatureData): GuardianCandidateStats {
    const level = Math.max(1, Math.floor(Number(creature.level) || 1));
    const prestige = Math.max(0, Math.floor(Number(creature.prestige) || 0));
    const rawPower = getCreatureCombatPower(creature);
    const combatPower = rawPower > 0
        ? rawPower
        : level * 10 + prestige * 50;
    return { level, prestige, combatPower };
}

export function compareGuardianCandidatesByPower(
    a: Pick<GuardianCandidateStats, 'combatPower' | 'prestige' | 'level'>,
    b: Pick<GuardianCandidateStats, 'combatPower' | 'prestige' | 'level'>,
): number {
    if (b.combatPower !== a.combatPower) return b.combatPower - a.combatPower;
    if (b.prestige !== a.prestige) return b.prestige - a.prestige;
    return b.level - a.level;
}
