import type {
    MiltankFarmSnapshot,
    MiltankFarmTalentBranchSnapshot,
    MiltankPastureHealOptionSnapshot,
    MiltankPastureSpriteSnapshot,
    BerryTreeSnapshot,
} from '../bus/snapshots.js';

function berryTreeSig(snapshot: BerryTreeSnapshot): string {
    return JSON.stringify({
        unlockedCount: snapshot.unlockedCount,
        combineDraft: snapshot.combineDraft.map((d) => d.itemKey),
        canTryCombine: snapshot.canTryCombine,
        combineInProgress: snapshot.combineInProgress,
        combineProgressPct: snapshot.combineProgressPct,
        combineQueueCount: snapshot.combineQueueCount,
        combineInFlightCount: snapshot.combineInFlightCount,
        combineMaxInFlight: snapshot.combineMaxInFlight,
        combineQueueCapacityLabel: snapshot.combineQueueCapacityLabel,
        combinePendingSlots: snapshot.combinePendingSlots.map((d) => d.itemKey),
        combineQueuePreview: snapshot.combineQueuePreview.map((row) => row.map((d) => d.itemKey)),
        combineQueueLevel: snapshot.combineQueueLevel,
        combineQueueMaxLevel: snapshot.combineQueueMaxLevel,
        canPurchaseCombineQueueUpgrade: snapshot.canPurchaseCombineQueueUpgrade,
        combineQueueUpgradeLabel: snapshot.combineQueueUpgradeLabel,
        combineQueueUpgradeCostLabel: snapshot.combineQueueUpgradeCostLabel,
        combineQueueUpgradeProgressLabel: snapshot.combineQueueUpgradeProgressLabel,
        showCombinePickerDuringProgress: snapshot.showCombinePickerDuringProgress,
        hotspotStoredQty: snapshot.hotspotStoredQty,
        canClaim: snapshot.canClaim,
        hasActiveCrop: snapshot.hasActiveCrop,
        cropBerryKey: snapshot.activeCrop?.berryKey ?? null,
        cropStored: snapshot.activeCrop?.storedQty ?? 0,
        cropFillPct: snapshot.activeCrop?.fillPct ?? 0,
        fertilizerActive: snapshot.fertilizerActive,
        almanacRevealed: snapshot.almanacEntries.map(
            (e) => [e.berryKey, e.canPlant, e.isActiveCrop, e.canQueue, e.isQueued, e.queuedCount, e.recipeSlots.map((s) => (s.revealed ? s.itemKey : null))],
        ),
        plantQueueLevel: snapshot.plantQueueLevel,
        plantQueueMaxLevel: snapshot.plantQueueMaxLevel,
        canPurchasePlantQueueUpgrade: snapshot.canPurchasePlantQueueUpgrade,
        plantQueueUpgradeLabel: snapshot.plantQueueUpgradeLabel,
        plantQueueUpgradeCostLabel: snapshot.plantQueueUpgradeCostLabel,
        plantQueueUpgradeProgressLabel: snapshot.plantQueueUpgradeProgressLabel,
        plantQueueLabel: snapshot.plantQueueLabel,
        plantQueueBerryKeys: snapshot.plantQueueBerryKeys,
        plantQueueCapacityLabel: snapshot.plantQueueCapacityLabel,
        plantOptions: snapshot.plantOptions.map((p) => [p.berryKey, p.isActive, p.canQueue, p.isQueued, p.queuedCount]),
        lastCombineAt: snapshot.lastCombineResult?.timestamp ?? 0,
        lastCombineOutcome: snapshot.lastCombineResult?.outcomeType ?? null,
        combineHistory: snapshot.combineHistory.map((entry) => [entry.timestamp, entry.outcomeType, entry.serializedArg]),
        draftAlreadyAttempted: snapshot.draftAlreadyAttempted,
        mulchCanApply: snapshot.mulchOptions.map((mulch) => [mulch.mulchKey, mulch.canApply, mulch.owned]),
    });
}

function pastureHealOptionsEqual(
    a: MiltankPastureHealOptionSnapshot[],
    b: MiltankPastureHealOptionSnapshot[],
): boolean {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
        const left = a[i];
        const right = b[i];
        if (!left || !right) return false;
        if (
            left.itemKey !== right.itemKey
            || left.owned !== right.owned
            || left.canUse !== right.canUse
            || left.blockedLabel !== right.blockedLabel
            || left.effectPreviewLabel !== right.effectPreviewLabel
        ) {
            return false;
        }
    }
    return true;
}

function talentBranchesEqual(
    a: MiltankFarmTalentBranchSnapshot[],
    b: MiltankFarmTalentBranchSnapshot[],
): boolean {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
        const left = a[i];
        const right = b[i];
        if (!left || !right) return false;
        if (
            left.key !== right.key
            || left.rank !== right.rank
            || left.canInvest !== right.canInvest
            || left.bonusText !== right.bonusText
            || left.nextBonusText !== right.nextBonusText
        ) {
            return false;
        }
    }
    return true;
}

function pastureSpritesEqual(
    a: MiltankPastureSpriteSnapshot[],
    b: MiltankPastureSpriteSnapshot[],
): boolean {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
        const left = a[i];
        const right = b[i];
        if (!left || !right) return false;
        if (
            left.uid !== right.uid
            || left.storedMilk !== right.storedMilk
            ||             left.pendingFraction !== right.pendingFraction
            || left.milkCyclePct !== right.milkCyclePct
            || left.hasGuardian !== right.hasGuardian
            || left.guardianUid !== right.guardianUid
            || left.debuffActive !== right.debuffActive
            || left.recentTheft !== right.recentTheft
            || left.recentRepelled !== right.recentRepelled
            || left.threatHitGlowDelayMs !== right.threatHitGlowDelayMs
            || left.isSelected !== right.isSelected
            || left.requestItemKey !== right.requestItemKey
            || left.requestItemIconUrl !== right.requestItemIconUrl
        ) {
            return false;
        }
    }
    return true;
}

/** Gameplay-relevant diff; excludes volatile timer labels/ms for dedup. */
export function miltankFarmSnapshotWouldChange(prev: MiltankFarmSnapshot, next: MiltankFarmSnapshot): boolean {
    return (
        prev.visible !== next.visible
        || prev.unlocked !== next.unlocked
        || prev.farmViewActive !== next.farmViewActive
        || prev.level !== next.level
        || prev.farmLevelSum !== next.farmLevelSum
        || prev.farmStoredMilk !== next.farmStoredMilk
        || prev.farmStockCap !== next.farmStockCap
        || prev.farmMilkPerHour !== next.farmMilkPerHour
        || prev.selectedPastureUid !== next.selectedPastureUid
        || prev.selectedPastureName !== next.selectedPastureName
        || prev.xp !== next.xp
        || prev.xpInLevel !== next.xpInLevel
        || prev.xpNeededInLevel !== next.xpNeededInLevel
        || prev.talentPointsAvailable !== next.talentPointsAvailable
        || !talentBranchesEqual(prev.talentBranches, next.talentBranches)
        || prev.storedMilk !== next.storedMilk
        || prev.stockCap !== next.stockCap
        || prev.pendingFraction !== next.pendingFraction
        || prev.milkPerHour !== next.milkPerHour
        || prev.requestItemKey !== next.requestItemKey
        || prev.requestItemName !== next.requestItemName
        || prev.requestItemIconUrl !== next.requestItemIconUrl
        || prev.requestQty !== next.requestQty
        || prev.requestOwned !== next.requestOwned
        || prev.canFeed !== next.canFeed
        || prev.canClaim !== next.canClaim
        || prev.canClaimSelected !== next.canClaimSelected
        || prev.satiety !== next.satiety
        || prev.boostActive !== next.boostActive
        || prev.pastureUpgraded !== next.pastureUpgraded
        || prev.rerollCost !== next.rerollCost
        || !pastureSpritesEqual(prev.pastureSprites, next.pastureSprites)
        || prev.maxAssignableSlots !== next.maxAssignableSlots
        || prev.assignedCount !== next.assignedCount
        || prev.nextPastureSlot !== next.nextPastureSlot
        || prev.pastureCandidates.length !== next.pastureCandidates.length
        || prev.pastureAssignSlots.length !== next.pastureAssignSlots.length
        || prev.combatActiveWhileFarm !== next.combatActiveWhileFarm
        || prev.farmThreatCombatActive !== next.farmThreatCombatActive
        || prev.feedBlockedReason !== next.feedBlockedReason
        || prev.feedBlockedLabel !== next.feedBlockedLabel
        || prev.canReroll !== next.canReroll
        || prev.rerollBlockedLabel !== next.rerollBlockedLabel
        || prev.farmHasClaimAction !== next.farmHasClaimAction
        || prev.farmHasFeedAction !== next.farmHasFeedAction
        || prev.farmHasTalentAction !== next.farmHasTalentAction
        || prev.farmActionBadgeCount !== next.farmActionBadgeCount
        || prev.pastureQuestHint !== next.pastureQuestHint
        || prev.vitaminEfficiencyPct !== next.vitaminEfficiencyPct
        || prev.milkPotencyNextPct !== next.milkPotencyNextPct
        || prev.threatsUnlocked !== next.threatsUnlocked
        || prev.guardiansUnlocked !== next.guardiansUnlocked
        || prev.guardianUnlockHint !== next.guardianUnlockHint
        || prev.guardianProgressHint !== next.guardianProgressHint
        || prev.guardianProgressClarify !== next.guardianProgressClarify
        || prev.hasActiveThreat !== next.hasActiveThreat
        || prev.threatAlertLabel !== next.threatAlertLabel
        || prev.threatCombatWins !== next.threatCombatWins
        || prev.threatIntensityLabel !== next.threatIntensityLabel
        || prev.incidentAlert?.type !== next.incidentAlert?.type
        || prev.incidentAlert?.title !== next.incidentAlert?.title
        || prev.incidentAlert?.body !== next.incidentAlert?.body
        || prev.hasRecentRepelled !== next.hasRecentRepelled
        || prev.selectedHasActiveThreat !== next.selectedHasActiveThreat
        || prev.selectedThreatAlertLabel !== next.selectedThreatAlertLabel
        || (prev.selectedPastureSprite?.uid ?? null) !== (next.selectedPastureSprite?.uid ?? null)
        || (prev.selectedPastureSprite?.hasGuardian ?? false) !== (next.selectedPastureSprite?.hasGuardian ?? false)
        || (prev.selectedPastureSprite?.guardianUid ?? null) !== (next.selectedPastureSprite?.guardianUid ?? null)
        || prev.threatApproachBannerLabel !== next.threatApproachBannerLabel
        || prev.pendingThreatEngageId !== next.pendingThreatEngageId
        || prev.hasApproachingThreat !== next.hasApproachingThreat
        || prev.activeThreatSprites.length !== next.activeThreatSprites.length
        || prev.activeThreatSprites.some((t, i) => {
            const other = next.activeThreatSprites[i];
            return !other
                || t.id !== other.id
                || Math.abs(t.progress - other.progress) > 0.03
                || t.walkClass !== other.walkClass
                || t.phase !== other.phase
                || t.approachSide !== other.approachSide
                || t.approachFacing !== other.approachFacing
                || t.displaySpecies !== other.displaySpecies;
        })
        || prev.threatCombatCandidates.length !== next.threatCombatCandidates.length
        || !pastureHealOptionsEqual(prev.pastureHealOptions, next.pastureHealOptions)
        || prev.berryTreeVisible !== next.berryTreeVisible
        || berryTreeSig(prev.berryTree) !== berryTreeSig(next.berryTree)
    );
}
