/**
 * @file src/lib/farmThreatSpecies.ts
 * Leaf helper for farm threat display species — no Creature / pokemonDefaultsBase.
 */

import { MILTANK_FARM_THREATS } from '../../constants/balance/miltankFarmThreats.ts';
import type { FarmThreatApproach } from './miltankFarmThreats.ts';

export function getFarmThreatCombatSpecies(approach: FarmThreatApproach): string {
    if (approach.type === 'rocket') {
        return MILTANK_FARM_THREATS.rocketCombatSpecies;
    }
    return approach.species;
}
