/**
 * Pasture threat defeat — lunge animation positions (mirrors farm-pasture.css approach paths).
 */

import { MILTANK_FARM_THREATS } from '../../constants/balance/miltankFarmThreats.ts';
import type { FarmThreatApproachSide } from './miltankFarmThreats.ts';

const APPROACH_PATHS: Record<
    number,
    { leftFrom: number; leftDelta: number; rightFrom: number; rightDelta: number; topFrom: number; topDelta: number }
> = {
    0: { leftFrom: 5, leftDelta: 23, rightFrom: 95, rightDelta: 67, topFrom: 18, topDelta: 40 },
    1: { leftFrom: 8, leftDelta: 47, rightFrom: 92, rightDelta: 37, topFrom: 16, topDelta: 32 },
    2: { leftFrom: 10, leftDelta: 62, rightFrom: 90, rightDelta: 18, topFrom: 20, topDelta: 42 },
};

const MILTANK_SLOT_POS: ReadonlyArray<{ left: number; top: number }> = [
    { left: 28, top: 58 },
    { left: 55, top: 48 },
    { left: 72, top: 62 },
];

export interface FarmPendingThreatAttack {
    id: string;
    pastureUid: string;
    type: 'predator' | 'rocket';
    species: string;
    threatLevel: number;
    approachSide: FarmThreatApproachSide;
    approachProgressAtStart: number;
    attackStartedAt: number;
    /** Timer expired — threat is on the Miltank; play bite glow immediately. */
    arrivedAtPasture?: boolean;
}

export function getThreatApproachPosition(
    slot: number,
    side: FarmThreatApproachSide,
    progress: number,
): { left: number; top: number } {
    const path = APPROACH_PATHS[Math.min(slot, 2)] ?? APPROACH_PATHS[0]!;
    const t = Math.max(0, Math.min(1, progress));
    const left = side === 'right'
        ? path.rightFrom - path.rightDelta * t
        : path.leftFrom + path.leftDelta * t;
    const top = path.topFrom + path.topDelta * t;
    return { left, top };
}

export function getMiltankSlotPosition(slot: number): { left: number; top: number } {
    return MILTANK_SLOT_POS[Math.min(slot, 2)] ?? MILTANK_SLOT_POS[0]!;
}

export function getThreatAttackLungeDurationMs(): number {
    return MILTANK_FARM_THREATS.threatAttackLungeDurationMs;
}

export function isThreatArrivedAtPasture(attack: FarmPendingThreatAttack): boolean {
    return !!attack.arrivedAtPasture;
}

export function getThreatAttackLungeDurationMsForAttack(attack: FarmPendingThreatAttack): number {
    if (isThreatArrivedAtPasture(attack)) {
        return MILTANK_FARM_THREATS.threatAttackArrivedLungeDurationMs;
    }
    return getThreatAttackLungeDurationMs();
}

export function getThreatAttackGlowPeakMs(): number {
    return Math.round(
        MILTANK_FARM_THREATS.threatAttackGlowDurationMs * MILTANK_FARM_THREATS.threatAttackGlowPeakRatio,
    );
}

export function getThreatAttackImpactAtMs(attack: FarmPendingThreatAttack): number {
    if (isThreatArrivedAtPasture(attack)) return 0;
    return MILTANK_FARM_THREATS.threatAttackLungeDurationMs;
}

export function getThreatAttackTotalDurationMs(attack?: FarmPendingThreatAttack): number {
    const impactAt = attack && isThreatArrivedAtPasture(attack)
        ? 0
        : MILTANK_FARM_THREATS.threatAttackLungeDurationMs;
    return impactAt
        + getThreatAttackGlowPeakMs()
        + MILTANK_FARM_THREATS.threatAttackThreatVanishAfterGlowPeakMs;
}

export function getThreatAttackProgress(attack: FarmPendingThreatAttack, now: number): number {
    const elapsed = Math.max(0, now - attack.attackStartedAt);
    const duration = getThreatAttackLungeDurationMs();
    if (duration <= 0) return 1;
    return Math.max(0, Math.min(1, elapsed / duration));
}

export function getThreatAttackLunge(
    attack: FarmPendingThreatAttack,
    slot: number,
    now: number,
): {
    fromLeft: number;
    fromTop: number;
    toLeft: number;
    toTop: number;
    elapsedMs: number;
} {
    const progressAtStart = isThreatArrivedAtPasture(attack)
        ? 1
        : attack.approachProgressAtStart;
    const start = getThreatApproachPosition(slot, attack.approachSide, progressAtStart);
    const end = getMiltankSlotPosition(slot);
    const lungeDuration = getThreatAttackLungeDurationMsForAttack(attack);
    const elapsedMs = lungeDuration > 0
        ? Math.max(0, now - attack.attackStartedAt)
        : 0;
    return {
        fromLeft: start.left,
        fromTop: start.top,
        toLeft: end.left,
        toTop: end.top,
        elapsedMs,
    };
}

export function getThreatHitGlowDelayMs(attack: FarmPendingThreatAttack, now: number): number {
    const impactAt = attack.attackStartedAt + getThreatAttackImpactAtMs(attack);
    return Math.max(0, impactAt - now);
}

export function getThreatAttackPosition(
    attack: FarmPendingThreatAttack,
    slot: number,
    now: number,
): { left: number; top: number; progress: number } {
    const progress = getThreatAttackProgress(attack, now);
    const ease = progress * progress;
    const start = getThreatApproachPosition(slot, attack.approachSide, attack.approachProgressAtStart);
    const end = getMiltankSlotPosition(slot);
    return {
        left: start.left + (end.left - start.left) * ease,
        top: start.top + (end.top - start.top) * ease,
        progress,
    };
}

export function shouldShowThreatHitGlow(attack: FarmPendingThreatAttack, now: number): boolean {
    return now >= attack.attackStartedAt + getThreatAttackImpactAtMs(attack);
}

export function isThreatAttackComplete(attack: FarmPendingThreatAttack, now: number): boolean {
    return now >= attack.attackStartedAt + getThreatAttackTotalDurationMs(attack);
}

export function pendingAttackToApproach(attack: FarmPendingThreatAttack): {
    id: string;
    pastureUid: string;
    type: 'predator' | 'rocket';
    species: string;
    threatLevel: number;
    startedAt: number;
    durationMs: number;
    approachSide: FarmThreatApproachSide;
} {
    return {
        id: attack.id,
        pastureUid: attack.pastureUid,
        type: attack.type,
        species: attack.species,
        threatLevel: attack.threatLevel,
        startedAt: attack.attackStartedAt,
        durationMs: 0,
        approachSide: attack.approachSide,
    };
}
