/**
 * @file src/lib/miltankFarmNarrative.ts
 * Display names for the narrative Miltank (Whitney / Blanche) vs assigned pasture entries.
 */

import type { GameRuntime } from '../types/game.js';
import { NARRATIVE_MILTANK_UID } from '../../constants/balance/miltankFarm.ts';
import type { MiltankFarmState, MiltankPastureEntry } from './miltankFarmLogic.ts';

function narrativeFarmT(game: GameRuntime, key: string, fallbackFr: string, fallbackEn: string): string {
    const lang = game && typeof game.normalizeLanguage === 'function'
        ? game.normalizeLanguage(game.language)
        : 'fr';
    if (typeof game.t === 'function') {
        const translated = game.t(key);
        if (translated && translated !== key) return translated;
    }
    return lang === 'en' ? fallbackEn : fallbackFr;
}

export function getNarrativeMiltankDisplayName(game: GameRuntime): string {
    return narrativeFarmT(
        game,
        'miltankFarm.narrativeName',
        'Miltank de Blanche',
        "Whitney's Miltank",
    );
}

export function getPastureEntryDisplayName(
    game: GameRuntime,
    state: MiltankFarmState,
    entry: MiltankPastureEntry,
): string {
    if (entry.isNarrative || entry.uid === NARRATIVE_MILTANK_UID) {
        return getNarrativeMiltankDisplayName(game);
    }
    const creature = (state.pastureCreatures ?? []).find((c) => String(c.uid) === entry.uid);
    return creature?.name || 'Miltank';
}
