import type { CreatureData } from '../types/creature.js';

type CombatPowerInput = Pick<
  CreatureData,
  'maxHp' | 'attack' | 'defense' | 'speed' | 'spattack' | 'spdefense'
>;

export function getCreatureCombatPower(creature: CombatPowerInput): number {
  return (
    creature.maxHp +
    creature.attack +
    creature.defense +
    creature.speed +
    (Number(creature.spattack) || 0) +
    (Number(creature.spdefense) || 0)
  );
}
