/**
 * @file src/lib/threatApproachFacing.ts
 * Overworld facing for farm threat approach trajectories (matches farm-pasture.css).
 */

import type { MiltankOwDir } from './miltankOverworldSprites.ts';
import type { FarmThreatApproachSide } from './miltankFarmThreats.ts';

/** Movement deltas (percentage points) per pasture slot and approach side. */
const THREAT_APPROACH_DELTAS: Readonly<Record<number, Readonly<Record<FarmThreatApproachSide, { dx: number; dy: number }>>>> = Object.freeze({
    0: Object.freeze({
        left: { dx: 23, dy: 40 },
        right: { dx: -67, dy: 40 },
    }),
    1: Object.freeze({
        left: { dx: 47, dy: 32 },
        right: { dx: -37, dy: 32 },
    }),
    2: Object.freeze({
        left: { dx: 62, dy: 42 },
        right: { dx: -18, dy: 42 },
    }),
});

export function getThreatApproachFacing(
    slot: number,
    side: FarmThreatApproachSide,
): MiltankOwDir {
    const deltas = THREAT_APPROACH_DELTAS[slot]?.[side] ?? THREAT_APPROACH_DELTAS[0]![side];
    const { dx, dy } = deltas;
    if (Math.abs(dx) >= Math.abs(dy)) {
        return dx > 0 ? 'right' : 'left';
    }
    return dy > 0 ? 'down' : 'up';
}
